def _write_question(out, v, depth):
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "asker")
    out += b": "
    _esc(out, v.asker)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "key")
    out += b": "
    _esc(out, v.key)
    if v.slots:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "slots")
        out += b": "
        _strmap(out, v.slots, depth + 1)
    out += b"\n"
    _pad(out, depth)
    out += b"}"


def _write_request(out, v, depth):
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "op")
    out += b": "
    _esc(out, v.op)
    if v.ask is not None:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "ask")
        out += b": "
        _write_question(out, v.ask, depth + 1)
    if v.wait:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "wait")
        out += b": "
        out += b"true" if v.wait else b"false"
    if v.id:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "id")
        out += b": "
        _esc(out, v.id)
    if v.option:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "option")
        out += b": "
        _esc(out, v.option)
    if v.admin:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "admin")
        out += b": "
        _esc(out, v.admin)
    out += b"\n"
    _pad(out, depth)
    out += b"}"


def _write_answer(out, v, depth):
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "id")
    out += b": "
    _esc(out, v.id)
    if v.pending:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "pending")
        out += b": "
        out += b"true" if v.pending else b"false"
    if v.option:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "option")
        out += b": "
        _esc(out, v.option)
    if v.yes:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "yes")
        out += b": "
        out += b"true" if v.yes else b"false"
    if v.kept:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "kept")
        out += b": "
        out += b"true" if v.kept else b"false"
    out += b"\n"
    _pad(out, depth)
    out += b"}"


def _write_record_metadata(out, v, depth):
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "id")
    out += b": "
    _esc(out, v.id)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "asker")
    out += b": "
    _esc(out, v.asker)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "key")
    out += b": "
    _esc(out, v.key)
    if v.about:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "about")
        out += b": "
        _esc(out, v.about)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "text")
    out += b": "
    _esc(out, v.text)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "options")
    out += b": "
    _strs(out, v.options, depth + 1)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
